# ── Example 2: mode="before" vs mode="after" ─────────────────────────
from pydantic import BaseModel, field_validator
from datetime import datetime, date

class EventModel(BaseModel):
    title:      str
    start_date: date
    end_date:   date
    capacity:   int
    price:      float

    # BEFORE mode: runs before type conversion
    # Input v is RAW (could be str, dict, anything)
    @field_validator("start_date", "end_date", mode="before")
    @classmethod
    def parse_flexible_date(cls, v):
        """Handle multiple date formats BEFORE Pydantic converts"""
        if isinstance(v, date):
            return v
        if isinstance(v, str):
            formats = ["%Y-%m-%d", "%d/%m/%Y", "%m-%d-%Y", "%d.%m.%Y"]
            for fmt in formats:
                try:
                    return datetime.strptime(v, fmt).date()
                except ValueError:
                    continue
            raise ValueError(f"Cannot parse date: {v!r}. Use YYYY-MM-DD")
        if isinstance(v, (int, float)):
            # Unix timestamp
            return datetime.fromtimestamp(v).date()
        raise ValueError(f"Invalid date type: {type(v)}")

    # AFTER mode: runs after type conversion
    # Input v is already the correct Python type (date, int, float)
    @field_validator("capacity", mode="after")
    @classmethod
    def validate_capacity(cls, v: int) -> int:
        """v is guaranteed to be int here"""
        if v < 1:
            raise ValueError("Capacity must be at least 1")
        if v > 100_000:
            raise ValueError("Capacity cannot exceed 100,000")
        return v

    @field_validator("price", mode="after")
    @classmethod
    def round_price(cls, v: float) -> float:
        """Round price to 2 decimal places"""
        return round(v, 2)

# Test different date formats (mode="before" handles raw strings)
event = EventModel(
    title="Python Conference",
    start_date="15/01/2025",    # DD/MM/YYYY
    end_date="2025-01-17",      # ISO format
    capacity="500",              # string → int (then after validator runs)
    price=99.999                 # rounded to 99.99
)

print(f"Title    : {event.title}")
print(f"Start    : {event.start_date} ({type(event.start_date).__name__})")
print(f"End      : {event.end_date}")
print(f"Capacity : {event.capacity}")
print(f"Price    : {event.price}")  # 100.0 (rounded)
