# ── Example 3: @model_validator — cross-field validation ──────────────
from pydantic import BaseModel, model_validator, field_validator, ValidationError
from typing import Optional
from datetime import date

class BookingRequest(BaseModel):
    guest_name:    str
    check_in:      date
    check_out:     date
    adults:        int
    children:      int = 0
    room_type:     str  # standard, deluxe, suite
    promo_code:    Optional[str] = None
    special_needs: Optional[str] = None

    # Field validators run first
    @field_validator("adults")
    @classmethod
    def validate_adults(cls, v: int) -> int:
        if v < 1:
            raise ValueError("At least 1 adult required")
        if v > 10:
            raise ValueError("Maximum 10 adults per booking")
        return v

    @field_validator("room_type")
    @classmethod
    def validate_room_type(cls, v: str) -> str:
        valid = {"standard", "deluxe", "suite", "family"}
        v = v.lower().strip()
        if v not in valid:
            raise ValueError(f"Invalid room type. Choose from: {valid}")
        return v

    # Model validator runs AFTER all field validators
    @model_validator(mode="after")
    def validate_booking_rules(self) -> "BookingRequest":
        """Cross-field validation — access all fields"""
        errors = []

        # Rule 1: check_out must be after check_in
        if self.check_out <= self.check_in:
            errors.append("check_out must be after check_in")

        # Rule 2: booking must be in the future
        if self.check_in < date.today():
            errors.append("check_in cannot be in the past")

        # Rule 3: max stay 30 days
        stay_days = (self.check_out - self.check_in).days
        if stay_days > 30:
            errors.append(f"Maximum stay is 30 days, got {stay_days}")

        # Rule 4: room type limits on occupancy
        room_limits = {"standard": 2, "deluxe": 3, "suite": 4, "family": 6}
        max_guests = room_limits.get(self.room_type, 2)
        total_guests = self.adults + self.children
        if total_guests > max_guests:
            errors.append(
                f"{self.room_type.title()} room max {max_guests} guests, "
                f"got {total_guests}"
            )

        # Rule 5: family room requires children
        if self.room_type == "family" and self.children == 0:
            errors.append("Family room requires at least 1 child")

        if errors:
            from pydantic import ValidationError
            raise ValueError(f"Booking rules violated: {'; '.join(errors)}")

        return self

    @model_validator(mode="before")
    @classmethod
    def normalize_input(cls, data: dict) -> dict:
        """Pre-process input before field validation"""
        if isinstance(data, dict):
            # Trim all string values
            return {k: v.strip() if isinstance(v, str) else v
                    for k, v in data.items()}
        return data

# Valid booking
from datetime import timedelta
today = date.today()
try:
    booking = BookingRequest(
        guest_name="Alice Johnson",
        check_in=today + timedelta(days=7),
        check_out=today + timedelta(days=10),
        adults=2,
        children=1,
        room_type="  Deluxe  "  # will be stripped and lowercased
    )
    stay = (booking.check_out - booking.check_in).days
    print(f"✅ Booking: {booking.guest_name}, {stay} nights, {booking.room_type}")
except ValidationError as e:
    print(f"❌ {e}")

# Invalid: check_out before check_in
try:
    BookingRequest(
        guest_name="Bob",
        check_in=today + timedelta(days=10),
        check_out=today + timedelta(days=7),  # BEFORE check_in!
        adults=2,
        room_type="standard"
    )
except ValidationError as e:
    print(f"❌ Cross-field error: {e.errors()[0]['msg']}")
