# ── Example 4: Validators for data transformation ─────────────────────
from pydantic import BaseModel, field_validator
from typing import List, Optional, Dict, Any
import re, json

class DataIngestionModel(BaseModel):
    """
    Model that TRANSFORMS data, not just validates.
    Validators normalize messy input into clean types.
    """
    raw_id:         str
    name:           str
    price_string:   str  # "$1,234.56" → stored as float
    tags_input:     Any  # could be str, list, None
    metadata_json:  Optional[str] = None  # JSON string → dict

    # Computed clean versions
    product_id:     str  = ""
    clean_price:    float = 0.0
    clean_tags:     List[str] = []
    parsed_metadata:Dict = {}

    @field_validator("raw_id", mode="before")
    @classmethod
    def normalize_id(cls, v: str) -> str:
        """Normalize: 'prod-001', 'PROD001', 'P-001' → 'PROD-001'"""
        v = re.sub(r'[^A-Z0-9]', '', v.upper())
        if not v:
            raise ValueError("ID cannot be empty after normalization")
        return v

    @field_validator("price_string", mode="before")
    @classmethod
    def parse_price(cls, v: Any) -> str:
        """Accept price in any format, return normalized string"""
        if isinstance(v, (int, float)):
            return str(round(float(v), 2))
        cleaned = re.sub(r'[^\d.,]', '', str(v))
        # Handle European format (1.234,56 → 1234.56)
        if re.match(r'^\d{1,3}(\.\d{3})*(,\d{2})?$', cleaned):
            cleaned = cleaned.replace('.','').replace(',','.')
        return cleaned

    @field_validator("tags_input", mode="before")
    @classmethod
    def parse_tags(cls, v: Any) -> Any:
        return v  # pass through — actual processing in __init__

    def model_post_init(self, __context: Any) -> None:
        """Called after all validators — final computed fields"""
        self.product_id = f"PROD-{self.raw_id}"

        try:
            self.clean_price = float(self.price_string.replace(",", ""))
        except ValueError:
            self.clean_price = 0.0

        if isinstance(self.tags_input, str):
            self.clean_tags = [t.strip().lower()
                              for t in self.tags_input.split(",") if t.strip()]
        elif isinstance(self.tags_input, list):
            self.clean_tags = [str(t).strip().lower() for t in self.tags_input if t]

        if self.metadata_json:
            try:
                self.parsed_metadata = json.loads(self.metadata_json)
            except json.JSONDecodeError:
                self.parsed_metadata = {}

# Test with messy data
record = DataIngestionModel(
    raw_id        = "prod-001",                 # normalized to PROD001
    name          = "Python Book",
    price_string  = "$1,299.99",               # parse to float
    tags_input    = "python,  programming, book",
    metadata_json = '{"category":"education","level":"advanced"}'
)

print(f"ID       : {record.product_id}")
print(f"Price    : {record.clean_price}")
print(f"Tags     : {record.clean_tags}")
print(f"Metadata : {record.parsed_metadata}")
