# ── Example 5: Real world — complete payment validation ───────────────
from pydantic import BaseModel, field_validator, model_validator, Field
from typing import Optional, Literal
from decimal import Decimal
from datetime import date
import re

class PaymentDetails(BaseModel):
    """Complete payment validation with cross-field rules"""
    amount:       Decimal = Field(..., gt=0, decimal_places=2)
    currency:     str
    payment_type: Literal["card", "bank", "wallet"]

    # Card fields
    card_number:  Optional[str] = None
    card_expiry:  Optional[str] = None  # MM/YY
    card_cvv:     Optional[str] = None
    card_holder:  Optional[str] = None

    # Bank fields
    account_number: Optional[str] = None
    routing_number: Optional[str] = None
    bank_name:      Optional[str] = None

    # Wallet fields
    wallet_id:    Optional[str] = None
    wallet_type:  Optional[str] = None

    @field_validator("currency")
    @classmethod
    def validate_currency(cls, v: str) -> str:
        valid = {"USD", "EUR", "GBP", "JPY", "INR", "CAD", "AUD"}
        v = v.upper().strip()
        if v not in valid:
            raise ValueError(f"Invalid currency: {v}. Valid: {valid}")
        return v

    @field_validator("card_number", mode="before")
    @classmethod
    def validate_card(cls, v: Optional[str]) -> Optional[str]:
        if v is None:
            return None
        digits = re.sub(r'\D', '', v)
        if not 13 <= len(digits) <= 19:
            raise ValueError("Card number must be 13-19 digits")
        # Luhn algorithm check
        total = 0
        for i, d in enumerate(reversed(digits)):
            n = int(d)
            if i % 2 == 1:
                n *= 2
                if n > 9:
                    n -= 9
            total += n
        if total % 10 != 0:
            raise ValueError("Invalid card number (Luhn check failed)")
        # Mask for storage: show only last 4
        return f"****-****-****-{digits[-4:]}"

    @field_validator("card_expiry")
    @classmethod
    def validate_expiry(cls, v: Optional[str]) -> Optional[str]:
        if v is None:
            return None
        match = re.match(r'^(\d{2})/(\d{2})$', v.strip())
        if not match:
            raise ValueError("Expiry must be MM/YY format")
        month, year = int(match.group(1)), int(match.group(2)) + 2000
        if not 1 <= month <= 12:
            raise ValueError("Invalid month in expiry")
        expiry = date(year, month, 1)
        if expiry < date.today().replace(day=1):
            raise ValueError("Card is expired")
        return v

    @model_validator(mode="after")
    def validate_payment_completeness(self) -> "PaymentDetails":
        """Ensure required fields are present for each payment type"""
        if self.payment_type == "card":
            missing = [f for f in ["card_number","card_expiry","card_cvv","card_holder"]
                      if not getattr(self, f)]
            if missing:
                raise ValueError(f"Card payment missing: {', '.join(missing)}")

        elif self.payment_type == "bank":
            missing = [f for f in ["account_number","routing_number","bank_name"]
                      if not getattr(self, f)]
            if missing:
                raise ValueError(f"Bank payment missing: {', '.join(missing)}")

        elif self.payment_type == "wallet":
            if not self.wallet_id:
                raise ValueError("Wallet payment requires wallet_id")

        # Currency limits
        limits = {"JPY": Decimal("1000000"), "USD": Decimal("10000")}
        limit  = limits.get(self.currency, Decimal("50000"))
        if self.amount > limit:
            raise ValueError(
                f"Amount {self.amount} exceeds limit "
                f"{limit} for {self.currency}"
            )
        return self

# Valid card payment (using test card number that passes Luhn)
from pydantic import ValidationError
try:
    payment = PaymentDetails(
        amount="99.99",
        currency="usd",
        payment_type="card",
        card_number="4532015112830366",  # valid test Visa
        card_expiry="12/28",
        card_cvv="123",
        card_holder="Alice Johnson"
    )
    print(f"✅ Payment: {payment.amount} {payment.currency}")
    print(f"   Card   : {payment.card_number}")  # masked!
except ValidationError as e:
    print(f"❌ {e}")
